style.css:
@-moz-document domain("roblox.com") {
html, body {
        background: url("https://wallpapercave.com/wp/wp8998058.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Make all main containers transparent */
    .container-main, .content, .navigation-container, .game-home-page, .page-content,
    .rbx-header, .rbx-footer, .section-content, .ng-scope, .home-container {
        background-color: transparent !important;
        background: none !important;
    }

    /* Optional: Remove annoying white headers or footers if needed */
    #header, #footer, .navbar {
        background: none !important;
    }
}
